const WORKSPACE_ID = 'T0BLLQ18E5C';
const CHANNEL_ID = 'C0BPQBNTK8R';
const CHANNEL_NAME = 'life-os-resource-inbox';
const IGNORED_SUBTYPES = new Set([
  'bot_message',
  'message_changed',
  'message_deleted',
  'channel_join',
  'channel_leave',
]);

function cleanUrl(value) {
  return value.replace(/[>.,;:!?\]})]+$/g, '');
}

function extractLinks(text) {
  const links = [];
  const slackLinkPattern = /<(https?:\/\/[^>|]+)(?:\|[^>]+)?>/g;
  const plainLinkPattern = /https?:\/\/[^\s<>()|>]+/g;
  for (const match of text.matchAll(slackLinkPattern)) links.push(cleanUrl(match[1]));
  for (const match of text.matchAll(plainLinkPattern)) links.push(cleanUrl(match[0]));
  return [...new Set(links)];
}

return $input.all().flatMap((item) => {
  const body = item.json?.body ?? item.json?.event ?? item.json ?? {};
  if (body.type === 'url_verification') {
    return [{ json: { challenge: body.challenge } }];
  }
  const event = body.event ?? body;
  const message = event.message ?? event;
  const channelId = event.channel ?? event.channel_id ?? event.item?.channel;
  const subtype = event.subtype ?? message.subtype ?? null;
  const messageTs = message.ts ?? event.ts;
  const threadTs = message.thread_ts ?? event.thread_ts ?? null;
  const authorId = message.user ?? event.user ?? null;
  const text = typeof message.text === 'string' ? message.text.trim() : '';
  const files = Array.isArray(message.files ?? event.files) ? (message.files ?? event.files) : [];

  if (channelId !== CHANNEL_ID || !messageTs) return [];
  if (event.bot_id || message.bot_id || IGNORED_SUBTYPES.has(subtype)) return [];
  if (!text && files.length === 0) return [];

  const links = extractLinks(text);
  const fileResources = files
    .filter((file) => file && typeof file.id === 'string')
    .map((file) => ({
      type: 'slack_file',
      id: file.id,
      name: typeof file.name === 'string' ? file.name : null,
      mime_type: typeof file.mimetype === 'string' ? file.mimetype : null,
      size_bytes: Number.isFinite(file.size) ? file.size : null,
    }));
  const timestampSeconds = Number.parseFloat(messageTs);
  const capturedAt = Number.isFinite(timestampSeconds)
    ? new Date(timestampSeconds * 1000).toISOString()
    : new Date().toISOString();

  return [{
    json: {
      schema_version: '1.0',
      source: 'slack_resource_inbox',
      content: text,
      primary_url: links[0] ?? null,
      resources: [
        ...links.map((url) => ({ type: 'link', url })),
        ...fileResources,
      ],
      source_metadata: {
        workspace_id: WORKSPACE_ID,
        channel_id: CHANNEL_ID,
        channel_name: CHANNEL_NAME,
        message_ts: String(messageTs),
        thread_ts: threadTs ? String(threadTs) : null,
        author_id: authorId ? String(authorId) : null,
      },
      captured_at: capturedAt,
      deduplication_key: `slack:${WORKSPACE_ID}:${CHANNEL_ID}:${messageTs}`,
      routing: {
        current_stage: 'ingestion',
        next_stages: ['cleaning', 'decision'],
        approval_required_for_external_actions: true,
      },
    },
  }];
});
